//! M24 #2 (RFC-0050 as amended by A1, ADR-0019): `sico:user/image-codec@1`
//! PNG bidirectional content contracts, asserted on the real runner Component
//! path against a frozen corpus.
//!
//! The decode corpus (`tests/corpus/image-codec`) is generated by an
//! INDEPENDENT oracle — `prototypes/image-codec-probe/tools/make-fixtures.py`
//! (Python `zlib` + manual chunk/CRC), sharing no code with the `png =0.18.1`
//! crate the guest core uses — and committed frozen with `manifest.json`
//! (schema `sico.m24.codec-fixtures.v0`). Expectations are read from that
//! manifest so the test and the oracle cannot drift apart.

use std::path::PathBuf;

use sico_codegen_wasm::package_builder::image_codec_package;
use wasmtime::component::{Component, Linker, Val};
use wasmtime::{Config, Engine, Store};

const INTERFACE: &str = "sico:user/image-codec@1.0.0";

fn engine() -> Engine {
    let mut config = Config::new();
    config.wasm_component_model(true);
    Engine::new(&config).unwrap()
}

/// Outcome of one codec call: `Ok(payload)` or `Err(case-name)`.
type CodecOutcome = Result<Vec<u8>, String>;

fn corpus_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/corpus/image-codec")
}

fn fixture(name: &str) -> Vec<u8> {
    std::fs::read(corpus_dir().join(name))
        .unwrap_or_else(|error| panic!("read fixture {name}: {error}"))
}

fn bytes_val(bytes: &[u8]) -> Val {
    Val::List(bytes.iter().map(|b| Val::U8(*b)).collect())
}

fn result_bytes(value: &Val) -> Vec<u8> {
    match value {
        Val::List(items) => items
            .iter()
            .map(|item| match item {
                Val::U8(b) => *b,
                other => panic!("unexpected list element {other:?}"),
            })
            .collect(),
        other => panic!("unexpected ok payload {other:?}"),
    }
}

/// Instantiates the package and calls one export, decoding the Canonical ABI
/// `Result[Bytes, Text]` return area (wasmtime 47 wraps the payload in
/// `Option<Box<Val>>`).
fn call(func: &str, args: &[Val]) -> CodecOutcome {
    let package = image_codec_package();
    let engine = engine();
    let component = Component::new(&engine, &package)
        .map_err(|error| panic!("component loads: {error:#}"))
        .expect("compiles");
    let mut store = Store::new(&engine, ());
    let linker = Linker::new(&engine);
    // The core is import-free (ADR-0019): an empty linker satisfies purity.
    let instance = linker
        .instantiate(&mut store, &component)
        .expect("instantiates against an empty linker");
    let inner = instance
        .get_export_index(&mut store, None, INTERFACE)
        .expect("interface instance exported");
    let func_index = instance
        .get_export_index(&mut store, Some(&inner), func)
        .unwrap_or_else(|| panic!("export {func} missing"));
    let callee = instance
        .get_func(&mut store, func_index)
        .expect("function resolves");
    let mut results = [Val::Result(Ok(None))];
    callee
        .call(&mut store, args, &mut results)
        .unwrap_or_else(|error| panic!("call {func} traps: {error:#}"));
    match &results[0] {
        Val::Result(Ok(Some(value))) => Ok(result_bytes(value.as_ref())),
        Val::Result(Ok(None)) => panic!("empty ok payload from {func}"),
        Val::Result(Err(Some(value))) => match value.as_ref() {
            Val::String(case) => Err(case.clone()),
            other => panic!("unexpected error payload {other:?}"),
        },
        Val::Result(Err(None)) => panic!("empty error payload from {func}"),
        other => panic!("unexpected result {other:?}"),
    }
}

fn decode(input: &[u8]) -> CodecOutcome {
    call("decode-png", &[bytes_val(input)])
}

fn encode(pixels: &[u8], width: u64, height: u64) -> CodecOutcome {
    call(
        "encode-png",
        &[bytes_val(pixels), Val::U64(width), Val::U64(height)],
    )
}

fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}

#[test]
fn image_codec_package_is_deterministic_and_pure() {
    let package = image_codec_package();
    assert_eq!(image_codec_package(), package, "two builds byte-identical");
    let engine = engine();
    let component = Component::new(&engine, &package)
        .map_err(|error| panic!("compile: {error:#}"))
        .unwrap();
    let ty = component.component_type();
    let mut exports = 0;
    for (name, item) in ty.exports(&engine) {
        assert!(name.starts_with("sico:user/image-codec@"), "{name}");
        assert!(matches!(
            item.ty,
            wasmtime::component::types::ComponentItem::ComponentInstance(_)
        ));
        exports += 1;
    }
    assert_eq!(exports, 1, "exactly one interface instance exported");
}

#[test]
fn decode_corpus_matches_independent_oracle() {
    let manifest: serde_json::Value =
        serde_json::from_str(include_str!("corpus/image-codec/manifest.json"))
            .expect("manifest parses");
    let cases = manifest["decode_cases"]
        .as_array()
        .expect("decode_cases array");
    assert_eq!(cases.len(), 9, "frozen 9-case decode corpus");
    let mut ok_seen = 0;
    let mut err_seen = 0;
    for case in cases {
        let name = case["name"].as_str().unwrap();
        let file = case["file"].as_str().unwrap();
        let input = fixture(file);
        let expect = &case["expect"];
        match expect["kind"].as_str().unwrap() {
            "ok" => {
                let want = expect["payload_hex"].as_str().unwrap();
                let got = decode(&input).unwrap_or_else(|c| panic!("{name}: refused with {c}"));
                assert_eq!(hex(&got), want, "{name}: byte-exact decode payload");
                ok_seen += 1;
            }
            "err" => {
                let want = expect["case"].as_str().unwrap();
                let got = decode(&input)
                    .err()
                    .unwrap_or_else(|| panic!("{name}: expected refusal {want}, got ok"));
                assert_eq!(got, want, "{name}: typed refusal");
                err_seen += 1;
            }
            other => panic!("{name}: unknown expect kind {other}"),
        }
    }
    assert_eq!((ok_seen, err_seen), (1, 8), "1 ok + 8 typed refusals");
}

#[test]
fn refusal_corpus_covers_the_a1_closed_set() {
    // RFC-0050 §3 closed CodecError set as completed by Amendment A1. The
    // decode corpus exercises every decode-reachable case; the encode-only
    // `encode-buffer-mismatch` is asserted below.
    let covered = [
        "bad-signature",
        "truncated",
        "trailing-data",
        "oversized",
        "unsupported-profile",
        "corrupt-stream",
    ];
    let manifest: serde_json::Value =
        serde_json::from_str(include_str!("corpus/image-codec/manifest.json")).unwrap();
    let observed: Vec<String> = manifest["decode_cases"]
        .as_array()
        .unwrap()
        .iter()
        .filter_map(|case| case["expect"]["case"].as_str().map(str::to_owned))
        .collect();
    for case in covered {
        assert!(
            observed.iter().any(|seen| seen == case),
            "refusal corpus missing {case}"
        );
    }
}

#[test]
fn encode_round_trips_and_is_byte_stable() {
    // Decode the frozen ok image to a header+BGRA payload, then re-encode its
    // pixels and decode again: the round trip must reproduce the payload, and
    // two encodes must be byte-identical (frozen Paeth/level-9/chunk set).
    let payload = decode(&fixture("ok-2x2-rgba.png")).expect("ok image decodes");
    assert!(payload.len() >= 16, "payload carries the 16-byte header");
    let width = u64::from_le_bytes(payload[0..8].try_into().unwrap());
    let height = u64::from_le_bytes(payload[8..16].try_into().unwrap());
    let pixels = &payload[16..];
    assert_eq!((width, height), (2, 2));
    assert_eq!(pixels.len(), (width * height * 4) as usize);

    let first = encode(pixels, width, height).unwrap_or_else(|c| panic!("encode refused: {c}"));
    let second = encode(pixels, width, height).expect("encode is total on valid input");
    assert_eq!(first, second, "encode is byte-stable across calls");

    let round = decode(&first).unwrap_or_else(|c| panic!("re-decode refused: {c}"));
    assert_eq!(
        round, payload,
        "decode(encode(x)) == x at the payload level"
    );
}

#[test]
fn encode_rejects_buffer_mismatch_with_the_a1_case() {
    // A pixel buffer whose length != width*height*4 is `encode-buffer-mismatch`
    // (the case Amendment A1 added), distinct from a malformed stream.
    let short = vec![0u8; 4 * 2 * 2 - 1];
    let got = encode(&short, 2, 2).expect_err("mismatched buffer refused");
    assert_eq!(got, "encode-buffer-mismatch");
}
